// Hard safety cap on results per run (cost protection — Apify is paid).
// Customer may request any number in Search Settings; this enforces a ceiling.
const HARD_CAP = 500;      // safety ceiling per run — customer sets max_results freely; only clamps a runaway typo
const SAFE_DEFAULT = 25;   // used when the input is blank / invalid

const s = $input.first().json;
const requestedRaw = s.max_results;
const n = Number(requestedRaw);

let applied;
if (!Number.isFinite(n) || n <= 0) {
  applied = SAFE_DEFAULT;                          // blank / invalid / zero / negative
} else {
  applied = Math.min(Math.floor(n), HARD_CAP);     // clamp anything above the cap
}

const requested = (requestedRaw === undefined || requestedRaw === null || requestedRaw === '')
  ? null : requestedRaw;

return [{ json: {
  business_type: s.business_type,
  location: s.location,
  industry: s.industry,
  requested_max_results: requested,   // what the customer asked for
  applied_max_results: applied        // what is actually sent to Apify (capped)
}}];

// Map Apify Google-Maps results into the EXACT Product 1 prospects schema,
// drop rows with no email, and append only NEW emails (dedup vs existing prospects).
const settings = $('⭐ Configure Your Search First').first().json;
const industry = (settings.industry || 'local business').toString();

// gather place records from the Apify response (handle array-in-item or split items)
let places = [];
for (const item of $('Find Businesses (Apify)').all()) {
  const j = item.json;
  if (Array.isArray(j)) places.push(...j);
  else if (j && Array.isArray(j.data)) places.push(...j.data);
  else if (j) places.push(j);
}

// existing prospect emails (this node's main input = Read Prospects)
const existing = new Set();
for (const it of $input.all()) {
  const e = (it.json.email || '').toString().trim().toLowerCase();
  if (e) existing.add(e);
}

// Email quality: drop obvious system / no-reply / monitoring addresses and malformed emails
// before a lead enters the pipeline. Conservative by design — keeps genuine business
// contacts (info@, sales@, office@, accounts@, support@ ...). No domain/disposable list.
//
// The shape test below is deliberately stricter than /^[^\s@]+@[^\s@]+\.[^\s@]+$/,
// which means only "something, one @, something containing a dot". A Google Maps
// URL satisfies that — its path becomes the local part and its trailing map
// coordinate becomes the "domain" — and one was stored as an email address in a
// real customer run. Structure is therefore checked label by label.
function isContactableEmail(e) {
  if (typeof e !== 'string' || !e) return false;
  if (/[\s<>()\[\],;:"\\]/.test(e)) return false;                   // whitespace / structural junk
  if (e.indexOf('/') !== -1) return false;                          // URL-shaped, incl. protocol-relative //host/path
  const parts = e.split('@');
  if (parts.length !== 2) return false;                             // exactly one @, never zero or two
  const local = parts[0], domain = parts[1];
  if (!local || local.length > 64) return false;
  if (!/^[a-z0-9._%+'&!#$*=?^`{|}~-]+$/i.test(local)) return false; // legal local-part characters only
  if (/^\.|\.$|\.\./.test(local)) return false;                     // no leading, trailing or doubled dot
  const labels = domain.split('.');
  if (labels.length < 2) return false;                              // a real domain is dotted
  if (!labels.every(l => /^[a-z0-9]([a-z0-9-]*[a-z0-9])?$/i.test(l))) return false;
  if (!/^[a-z]{2,}$/i.test(labels[labels.length - 1])) return false; // alphabetic TLD, never a map coordinate
  const BLOCK = /^(no-?reply|do-?not-?reply|donotreply|bounce(s)?|mailer-daemon|postmaster|sentry|errors?|monitoring|alerts?|notifications?|cron|automated|wordpress)([._-]|$)/;
  return !BLOCK.test(local);                                        // system/no-contact local-part
}

const seen = new Set();
const out = [];
for (const pl of places) {
  const email = ((pl.emails && pl.emails[0]) || pl.email || '').toString().trim().toLowerCase();
  if (!email) continue;                       // no email -> not usable for outreach, skip
  if (!isContactableEmail(email)) continue;   // drop system/no-reply/monitoring + malformed
  if (existing.has(email) || seen.has(email)) continue;  // dedup vs sheet + within batch
  seen.add(email);
  const notes = [pl.phone, pl.website, pl.address, pl.categoryName]
                  .filter(Boolean).join(' | ');
  out.push({ json: {
    name: '',                                 // Maps has no contact first name
    company: (pl.title || '').toString(),
    email: email,
    role: '',
    industry: industry,                       // chosen per search -> picks the P1 template
    linkedin_url: (pl.linkedIns && pl.linkedIns[0]) || '',
    notes: notes
  }});
}
return out;
